INSERT INTO movies (title, english_title, director, cast_members, genre, release_year, runtime_minutes, country, naver_rating, description, keywords, poster_url, naver_movie_id) VALUES ('마녀2', 'The Witch: Part 2', '박훈정', '{"신시아","박은빈"}', 'Action', 2022, 145, 'South Korea', 9.0, 'Action 장르의 대작으로, 박훈정 감독의 연출과 신시아의 뛰어난 액션 연기가 돋보이는 작품이다.', '{"마녀2","박훈정","신시아","Action","2022"}', NULL, 272890);
